      fail:{t:"Quelques tours tombent, les principales tiennent.",e:{t:-2,no:-4}},
      part:{t:"La côte est soumise, l'intérieur non. Le chemin de Compostelle redevient praticable.",e:{au:6,pr:5,no:-6}},
      succ:{t:"Les forteresses galiciennes tombent une à une. Une province entière rentre dans le royaume.",e:{au:12,pr:8,t:4,no:-8}},
